    "html": "<!doctype html>\n<html lang=\"zh-CN\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"x-apple-disable-message-reformatting\" />\n  <meta name=\"format-detection\" content=\"telephone=no,address=no,email=no,date=no,url=no\" />\n  <meta name=\"color-scheme\" content=\"light\" />\n  <meta name=\"supported-color-schemes\" content=\"light\" />\n  <title>你的账户已注销</title>\n  <!--[if mso]><noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript><![endif]-->\n  <style>\n    @media screen and (max-width:680px) {\n      .outer-pad{padding:14px 8px!important}.email-shell{width:100%!important}.main-pad{padding-left:24px!important;padding-right:24px!important}.top-pad{padding-top:28px!important}.title{font-size:30px!important;line-height:39px!important}.otp-panel{padding:26px 14px 22px!important}.otp-code{font-size:39px!important;line-height:48px!important;letter-spacing:2px!important}.notice-copy{font-size:14px!important;line-height:24px!important}.footer-left,.footer-right{display:block!important;width:100%!important;text-align:left!important}.footer-right{padding-top:16px!important}\n    }\n  </style>\n</head>\n<body style=\"margin:0;padding:0;background:#f3f7fc;background-image:linear-gradient(135deg,#f3f7fc 0%,#eef5ff 50%,#f3f7fc 100%);color:#0a1831;font-family:Arial,'PingFang SC','Microsoft YaHei',sans-serif\">\n  <div style=\"display:none!important;width:0;height:0;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px;mso-hide:all\">你的 DOSO 账户已注销。&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;</div>\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#f3f7fc\" style=\"width:100%;border-collapse:collapse;background:#f3f7fc;background-image:linear-gradient(135deg,#f3f7fc 0%,#eef5ff 50%,#f3f7fc 100%)\"><tr><td class=\"outer-pad\" align=\"center\" valign=\"top\" style=\"padding:28px 12px\">\n  <!--[if mso]><table role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td><![endif]-->\n  <table class=\"email-shell\" role=\"presentation\" width=\"640\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#ffffff\" style=\"width:100%;max-width:640px;border-collapse:separate;table-layout:fixed;background:#ffffff;border:1px solid #d8e5f6;border-radius:12px\">\n    <tr><td class=\"main-pad top-pad\" style=\"padding:38px 48px 0\"><img src=\"https://vchvqfdlkomlrjenkdhj.supabase.co/storage/v1/object/public/email-assets/doso-robotics-wordmark-email-29dea10fd204.png\" width=\"180\" height=\"60\" alt=\"DOSO robotics\" style=\"display:block;width:180px;height:60px;border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic\" /></td></tr>\n    <tr><td class=\"main-pad\" style=\"padding:30px 48px 0\">\n<h1 class=\"title\" style=\"margin:0;font-size:36px;line-height:46px;font-weight:700;color:#0b1f3f\">你的账户已注销</h1>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:22px;border-collapse:collapse\"><tr><td width=\"36\" height=\"4\" bgcolor=\"#0b5fff\" style=\"width:36px;height:4px;font-size:0;line-height:0;background:#0b5fff\">&nbsp;</td></tr></table><div style=\"height:24px;line-height:24px\">&nbsp;</div><p style=\"margin:0;font-size:17px;line-height:30px;color:#22314d;\">你的 DOSO 账户已注销成功。</p></td></tr>\n    <tr><td class=\"main-pad\" style=\"padding:26px 48px 0\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#f5f9ff\" style=\"width:100%;border-collapse:separate;table-layout:fixed;background:#f5f9ff;border:1px solid #d8e5f6;border-radius:16px\"><tbody><tr>\n    <td width=\"31%\" style=\"padding:18px 18px;font-size:15px;line-height:24px;font-weight:700;color:#0b1f3f;\">账户</td>\n    <td style=\"padding:18px 18px;font-size:15px;line-height:24px;color:#22314d;word-break:break-word;\">{{account_email}}</td>\n  </tr><tr>\n    <td width=\"31%\" style=\"padding:18px 18px;font-size:15px;line-height:24px;font-weight:700;color:#0b1f3f;border-top:1px solid #d8e5f6;\">时间</td>\n    <td style=\"padding:18px 18px;font-size:15px;line-height:24px;color:#22314d;word-break:break-word;border-top:1px solid #d8e5f6;\">{{event_time}}</td>\n  </tr></tbody></table></td></tr>\n    <tr><td class=\"main-pad\" style=\"padding:34px 48px 0\">\n    \n    <p style=\"margin:0;font-size:18px;line-height:27px;font-weight:700;color:#0b1f3f\">感谢使用 DOSO robotics</p>\n    <p class=\"notice-copy\" style=\"margin:6px 0 0;font-size:15px;line-height:26px;color:#526581\">如果仍有任何问题，请联系 DOSO 客服。</p>\n    \n  </td></tr>\n    <tr><td class=\"main-pad\" style=\"padding:38px 48px 34px\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:100%;border-collapse:collapse;border-top:1px solid #d8e5f6\"><tr>\n      <td class=\"footer-left\" width=\"50%\" valign=\"bottom\" style=\"width:50%;padding-top:26px;text-align:left\"><img src=\"https://vchvqfdlkomlrjenkdhj.supabase.co/storage/v1/object/public/email-assets/doso-robotics-wordmark-email-29dea10fd204.png\" width=\"120\" height=\"40\" alt=\"\" style=\"display:block;width:120px;height:40px;border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic\" /><p style=\"margin:7px 0 0;font-size:12px;line-height:20px;color:#526581\">Robotics for the real world.</p></td>\n      <td class=\"footer-right\" width=\"50%\" valign=\"bottom\" align=\"right\" style=\"width:50%;padding-top:26px;text-align:right\"><p style=\"margin:0;font-size:12px;line-height:21px;color:#526581\">© 2026 DOSO Robotics<br />此邮件由系统自动发送，请勿回复。</p></td>\n    </tr></table></td></tr>\n  </table>\n  <!--[if mso]></td></tr></table><![endif]-->\n  </td></tr></table>\n</body>\n</html>\n",
